CREATE TABLE IF NOT EXISTS money_dp_record (ref VARCHAR(100) NOT NULL, fy SMALLINT NOT NULL, service_date DATE NOT NULL, claim DECIMAL(15,2) NOT NULL, eligible DECIMAL(15,2) NOT NULL, flagged TINYINT(1) NOT NULL, record_ciphertext MEDIUMTEXT NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (ref), KEY money_dp_record_fy (fy, service_date), CONSTRAINT money_dp_record_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS money_dp_upload (upload_id CHAR(36) NOT NULL, fy SMALLINT NOT NULL, file_name VARCHAR(255) NOT NULL, row_count INT NOT NULL, uploaded_at DATETIME(6) NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (upload_id, fy), KEY money_dp_upload_fy (fy, uploaded_at), CONSTRAINT money_dp_upload_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
